import React, { useState } from 'react';
import { OverlayPanel } from 'primereact/overlaypanel';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="overlayPanel-accessibility">Accessible OverlayPanel</label>
            <OverlayPanel 
                id="overlayPanel-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible OverlayPanel input"
                placeholder="Enter overlayPanel"
            />
        </div>
    );
}